/**
 * Multi-Paradigm DUI Update Phase
 *
 * Updates 4 paradigm scores based on simulation state each month.
 * Maps democracy, QoL, environment, and social cohesion to paradigm scores.
 *
 * **Phase Order:** 34.1 (after QoL updates, before outcome detection)
 *
 * @module simulation/engine/phases/MultiParadigmDUIUpdatePhase
 */

import type { GameState, RNGFunction } from '@/types/game';
import type { SimulationPhase, PhaseResult, PhaseContext } from '../PhaseOrchestrator';
import { calculateDivergence } from '@/data/aggregators/divergenceCalculator';
import { calculateCorrelations } from '@/data/aggregators/correlationTracker';
import { classifyOutcome } from '@/data/aggregators/outcomeClassifier';

/**
 * Multi-Paradigm DUI Update Phase
 *
 * Updates paradigm scores based on simulation state.
 */
export class MultiParadigmDUIUpdatePhase implements SimulationPhase {
  readonly id = 'multi_paradigm_dui_update';
  readonly name = 'Multi-Paradigm DUI Update';
  readonly order = 34.1;

  execute(state: GameState, rng: RNGFunction, context?: PhaseContext): PhaseResult {
    // Calculate new paradigm scores from simulation state
    const scores = calculateParadigmScoresFromState(state);

    // Debug logging for first month
    if (state.currentMonth === 0) {
      console.log(`🌍 MultiParadigm Month 0: W=${scores.western.toFixed(1)}, D=${scores.development.toFixed(1)}, E=${scores.ecological.toFixed(1)}, I=${scores.indigenous.toFixed(1)}`);
      console.log(`   democracy exists: ${!!state.government.democracy}, socialCohesion exists: ${!!state.socialCohesion}`);
    }

    // Update paradigm scores
    state.multiParadigmDUI.paradigmScores.western.value = scores.western;
    state.multiParadigmDUI.paradigmScores.development.value = scores.development;
    state.multiParadigmDUI.paradigmScores.ecological.value = scores.ecological;
    state.multiParadigmDUI.diagnosticLenses.indigenous.value = scores.indigenous;

    // Add to history
    state.multiParadigmDUI.history.push({
      month: state.currentMonth,
      western: scores.western,
      development: scores.development,
      ecological: scores.ecological,
      indigenous: scores.indigenous,
    });

    // Calculate divergence (with trend detection if enough history)
    state.multiParadigmDUI.divergence = calculateDivergence(scores, state.multiParadigmDUI.history);

    // Calculate outcome classification
    state.multiParadigmDUI.outcome = classifyOutcome(scores);

    // Update legacy DUI (derive from Development paradigm)
    state.globalMetrics.dystopiaUtopiaIndex = scores.development;

    return {
      events: [`Multi-Paradigm DUI updated: W=${scores.western.toFixed(1)} D=${scores.development.toFixed(1)} E=${scores.ecological.toFixed(1)} I=${scores.indigenous.toFixed(1)}`],
    };
  }
}

/**
 * Calculate paradigm scores from simulation state
 *
 * Maps simulation state (democracy, QoL, environment, social) to 4 paradigm scores.
 *
 * @param state - Current game state
 * @returns 4 paradigm scores (0-100)
 */
function calculateParadigmScoresFromState(state: GameState): {
  western: number;
  development: number;
  ecological: number;
  indigenous: number;
} {
  let western = calculateWesternLiberal(state);
  let development = calculateDevelopment(state);
  let ecological = calculateEcological(state);
  let indigenous = calculateIndigenous(state);

  // Ensure no NaN/undefined values (fallback to neutral 50)
  if (isNaN(western) || western === undefined) western = 50;
  if (isNaN(development) || development === undefined) development = 50;
  if (isNaN(ecological) || ecological === undefined) ecological = 50;
  if (isNaN(indigenous) || indigenous === undefined) indigenous = 50;

  return { western, development, ecological, indigenous };
}

/**
 * Calculate Western Liberal paradigm score from simulation state
 *
 * **SCORING REDESIGN (Oct 21, 2025):** Expose component scores instead of compressing into geometric mean.
 * Geometric mean invokes Goodhart's Law - when one component collapses, headline number obscures nuance.
 *
 * Indicators (now tracked separately):
 * - Electoral Democracy (40%): state.government.democracy.electoralDemocracyIndex (0-100)
 * - Civil Liberties (30%): state.socialCohesion.civilLiberties (0-100)
 * - Rule of Law (20%): state.government.democracy.ruleOfLaw (0-100)
 * - Economic Freedom (10%): 100 - state.government.economicPolicy.marketRegulation (0-100)
 *
 * Components stored in state.multiParadigmDUI.westernLiberalComponents for analysis.
 *
 * @param state - Current game state
 * @returns Western Liberal score (0-100) - STILL geometric mean for backward compatibility, but components tracked
 */
function calculateWesternLiberal(state: GameState): number {
  const MIN_FLOOR = 0.1;

  // Electoral Democracy (0-1 → 0-100)
  const electoralDemocracy = (state.government.democracy?.electoralDemocracyIndex ?? 0.5) * 100;

  // Civil Liberties (0-100)
  const civilLiberties = state.socialCohesion?.civilLiberties ?? 50;

  // Rule of Law (0-100)
  const ruleOfLaw = state.government.democracy?.ruleOfLaw ?? 50;

  // Economic Freedom (inverted market regulation)
  const economicFreedom = 100 - (state.government.economicPolicy?.marketRegulation ?? 50);

  // STORE COMPONENTS for decomposed analysis (avoiding Goodhart's Law)
  if (!state.multiParadigmDUI.westernLiberalComponents) {
    state.multiParadigmDUI.westernLiberalComponents = [];
  }

  state.multiParadigmDUI.westernLiberalComponents.push({
    month: state.currentMonth,
    electoralDemocracy,
    civilLiberties,
    ruleOfLaw,
    economicFreedom,
  });

  // Geometric mean (non-compensatory) - KEPT for backward compatibility
  // BUT: Users should analyze components, not this headline number
  const indicators = [electoralDemocracy, civilLiberties, ruleOfLaw, economicFreedom];
  const product = indicators.reduce((acc, val) => {
    const floored = Math.max(val ?? 50, MIN_FLOOR);
    return acc * (floored / 100);
  }, 1);

  const result = Math.pow(product, 1 / indicators.length) * 100;
  return isNaN(result) ? 50 : result;
}

/**
 * Calculate Development paradigm score from simulation state
 *
 * Indicators:
 * - Quality of Life (50%): state.globalMetrics.qualityOfLife (converted from 0-1 to 0-100)
 * - Survival Fundamentals (30%): Geometric mean of food, water, thermal, shelter security
 * - Healthcare Quality (20%): state.qualityOfLifeSystems.healthcareQuality (0-1 → 0-100)
 *
 * @param state - Current game state
 * @returns Development score (0-100)
 */
function calculateDevelopment(state: GameState): number {
  const MIN_FLOOR = 0.1;

  // Quality of Life (0-1 → 0-100, primary driver)
  const qolRaw = state.globalMetrics.qualityOfLife ?? 0.5;
  const qol = qolRaw * 100;

  // Survival Fundamentals (geometric mean of 4 survival dimensions, 0-1 → 0-100)
  const survival = state.qualityOfLifeSystems?.survivalFundamentals;
  let survivalScore = 50;
  if (survival) {
    const food = Math.max(MIN_FLOOR, Math.min(1, survival.foodSecurity ?? 0.5));
    const water = Math.max(MIN_FLOOR, Math.min(1, survival.waterSecurity ?? 0.5));
    const thermal = Math.max(MIN_FLOOR, Math.min(1, survival.thermalHabitability ?? 0.8));
    const shelter = Math.max(MIN_FLOOR, Math.min(1, survival.shelterSecurity ?? 0.5));
    survivalScore = Math.pow(food * water * thermal * shelter, 1/4) * 100;
  }

  // Healthcare Quality (0-1 → 0-100)
  const healthcareRaw = state.qualityOfLifeSystems?.healthcareQuality ?? 0.5;
  const healthcare = healthcareRaw * 100;

  // Geometric mean
  const indicators = [qol, survivalScore, healthcare];
  const product = indicators.reduce((acc, val) => {
    const floored = Math.max(val ?? 50, MIN_FLOOR);
    return acc * (floored / 100);
  }, 1);

  const result = Math.pow(product, 1 / indicators.length) * 100;
  return isNaN(result) ? 50 : result;
}

/**
 * Calculate Ecological paradigm score from simulation state
 *
 * UPDATED (Oct 21, 2025 - FIX #14): Uses progressive recovery scoring system
 * - Replaces binary breach counting with impact-weighted recovery progress
 * - Gives credit for partial recovery before full boundary un-breach
 * - Research-backed weights based on mortality potential
 *
 * Indicators:
 * - Planetary Boundaries (50%): Progressive recovery score (0-100)
 * - Resource Depletion (25%): 100 - resourceDepletion
 * - Climate Stability (15%): 100 - (temperatureAnomaly / 2.0) * 100
 * - Pollution (10%): 100 - pollutionLevel
 *
 * SCORE INTERPRETATION (Empirically Realistic, FIX #14):
 * - **0-10 (Catastrophic Collapse):**
 *     Most/all boundaries breached, cascades active, mass mortality
 *     Expected frequency: 15-25% of runs
 *
 * - **10-30 (Stabilized):**
 *     Boundaries still breached but not worsening, technologies deployed,
 *     emissions declining but ecosystem damage persists
 *     Expected frequency: 40-50% of runs (MOST REALISTIC OUTCOME)
 *     This is NOT dystopia - represents sustainable development path
 *
 * - **30-60 (Recovering):**
 *     Some boundaries un-breached, partial restoration underway,
 *     sustained net-negative emissions, slow healing
 *     Expected frequency: 25-35% of runs
 *     Requires 10-30 years sustained action post-net-zero
 *
 * - **60-100 (Restored):**
 *     Most boundaries safe, ecosystem resilience restored,
 *     full environmental health achieved
 *     Expected frequency: 5-10% of runs (HEROIC ACTION + 50-100 YEARS)
 *     Requires 50-100 years sustained effort beyond simulation timeframe
 *
 * CRITICAL: 10-30/100 is NOT failure - it's empirically realistic stabilization.
 * Full restoration (60-100) takes 50-100 years beyond most simulation runs.
 *
 * @param state - Current game state
 * @returns Ecological score (0-100)
 */
function calculateEcological(state: GameState): number {
  const MIN_FLOOR = 0.1;

  // Planetary Boundaries: Use progressive recovery scoring (Oct 21, 2025)
  // Replaces simple binary breach counting with impact-weighted recovery progress
  const { calculateProgressiveEcologicalScore } = require('../../planetaryBoundaryRecovery');
  const boundariesScore = calculateProgressiveEcologicalScore(state);

  // Resource Depletion (0-100, inverted)
  const resourceDepletion = state.environmentalAccumulation?.resourceDepletion ?? 30;
  const resourceScore = 100 - resourceDepletion;

  // Climate Stability (temperature anomaly, 0-2°C → 100-0)
  const temperatureAnomaly = state.environmental?.climateState?.globalTemperatureAnomaly ?? 1.0;
  const climateScore = Math.max(0, 100 - (temperatureAnomaly / 2.0) * 100);

  // Pollution (0-100, inverted)
  const pollutionLevel = state.environmental?.pollutionLevel ?? 40;
  const pollutionScore = 100 - pollutionLevel;

  // Geometric mean
  const indicators = [boundariesScore, resourceScore, climateScore, pollutionScore];
  const product = indicators.reduce((acc, val) => {
    const floored = Math.max(val ?? 50, MIN_FLOOR);
    return acc * (floored / 100);
  }, 1);

  const result = Math.pow(product, 1 / indicators.length) * 100;
  return isNaN(result) ? 50 : result;
}

/**
 * Calculate Indigenous paradigm score from simulation state
 *
 * Indicators:
 * - Social Trust (40%): state.socialCohesion.trust
 * - Community Bonds (40%): state.socialCohesion.communityBonds
 * - Meaning Crisis (20%): 100 - meaningCrisis (inverted)
 *
 * @param state - Current game state
 * @returns Indigenous score (0-100)
 */
function calculateIndigenous(state: GameState): number {
  const MIN_FLOOR = 0.1;

  // Social Trust (0-100)
  const socialTrust = state.socialCohesion?.trust ?? 50;

  // Community Bonds (0-100)
  const communityBonds = state.socialCohesion?.communityBonds ?? 50;

  // Meaning Crisis (0-100, inverted)
  const meaningCrisis = state.socialAccumulation?.meaningCrisis ?? 50;
  const meaningScore = 100 - meaningCrisis;

  // Geometric mean
  const indicators = [socialTrust, communityBonds, meaningScore];
  const product = indicators.reduce((acc, val) => {
    const floored = Math.max(val ?? 50, MIN_FLOOR);
    return acc * (floored / 100);
  }, 1);

  const result = Math.pow(product, 1 / indicators.length) * 100;
  return isNaN(result) ? 50 : result;
}

/**
 * Multi-Paradigm Dystopia-Utopia Index (DUI)
 *
 * Models dystopia/utopia through four distinct paradigmatic lenses,
 * showing fundamental value conflicts rather than false universal consensus.
 *
 * Core Insight: Singapore is simultaneously a Development utopia (HDI 0.939)
 * AND Western dystopia (Freedom House 48/100). Norway is Western/Development
 * utopia AND Ecological dystopia (oil economy). Paradigm conflicts are
 * diagnostic, not errors.
 *
 * Three-Tier Architecture:
 * - Tier 1: Simulation Foundation (what drives outcomes - already exists)
 * - Tier 2A: High-Confidence Paradigms (drive + report)
 * - Tier 2B: Reporting-Only Paradigms (diagnostic lens)
 *
 * Research Foundation:
 * - Phase 1: 4 paradigm documents (~55,000 words, 100+ sources)
 * - Phase 2: 42 indicators mapped (9 Western, 14 Development, 12 Ecological, 7 Indigenous)
 * - Quality Gates: 73% confidence (Phase 1), 68% confidence (Phase 2)
 *
 * @module types/multiParadigmDUI
 */

/**
 * Confidence level for paradigm scores
 *
 * HIGH: Official data, 180+ countries, annual updates (V-Dem, UNDP, WHO)
 * MEDIUM: Official data, limited countries or irregular updates (WVS, some boundaries)
 * LOW: Proxy indicators, substantial uncertainty (Indigenous paradigm proxies)
 * SPECULATIVE: Estimated, no direct measurement
 */
export type ConfidenceLevel = 'HIGH' | 'MEDIUM' | 'LOW' | 'SPECULATIVE';

/**
 * Uncertainty band for paradigm scores
 *
 * Captures measurement error, model uncertainty, and data gaps.
 * Example: Ecological paradigm has ±50% uncertainty on some boundaries.
 */
export interface UncertaintyBand {
  /** Pessimistic bound (lower estimate) */
  low: number;

  /** Optimistic bound (upper estimate) */
  high: number;

  /** Source of uncertainty (measurement error, model, data gap) */
  source: string;
}

/**
 * Individual indicator within a paradigm
 *
 * Each paradigm aggregates 5-15 indicators using geometric mean.
 */
export interface ParadigmIndicator {
  /** Indicator ID (e.g., 'vdem_electoral_democracy') */
  id: string;

  /** Human-readable name */
  name: string;

  /** Current value (0-100 scale) */
  value: number;

  /** Weight in paradigm aggregation (typically 1/N for equal weights) */
  weight: number;

  /** Confidence level for this indicator */
  confidence: ConfidenceLevel;

  /** Does this indicator have actual data (vs imputed/derived)? */
  hasData: boolean;

  /** Uncertainty band (if applicable) */
  uncertaintyBand?: UncertaintyBand;
}

/**
 * Paradigm score (0-100)
 *
 * Aggregated using geometric mean (non-compensatory):
 * - A single low indicator significantly lowers overall score
 * - Prevents "elite utopia" scenarios (high average masking severe deficits)
 * - Matches UNDP HDI methodology
 */
export interface ParadigmScore {
  /** Aggregate score (0-100) */
  value: number;

  /** Confidence level for overall paradigm */
  confidence: ConfidenceLevel;

  /** Data availability (0-1): % of indicators with actual data */
  dataAvailability: number;

  /** Uncertainty band (if applicable) */
  uncertaintyBand?: UncertaintyBand;

  /** Component indicators (5-15 per paradigm) */
  indicators: ParadigmIndicator[];

  /** Breakdown by dimension (optional, for detailed reporting) */
  dimensions?: Record<string, number>;

  /** Which systems/data sources this paradigm derives from */
  derivedFrom: string[];
}

/**
 * Diagnostic lens paradigm (reporting-only, doesn't drive simulation)
 *
 * Used for paradigms with incomplete data (Indigenous/Communitarian).
 * Derives scores from existing simulation mechanics + proxies where available.
 */
export interface DiagnosticLens extends ParadigmScore {
  /** Explicitly mark as non-driving */
  drivesSimulation: false;

  /** Caveat for users about data limitations */
  caveat: string;

  /** Breakdown of score derivation */
  derivation: {
    /** % from existing simulation mechanics (e.g., social cohesion) */
    fromSimulation: number;

    /** % from proxy indicators (e.g., WVS social trust) */
    fromProxies: number;

    /** % estimated/imputed */
    estimated: number;
  };
}

/**
 * Paradigm divergence metrics
 *
 * Tracks how much paradigms disagree (the diagnostic value!).
 */
export interface ParadigmDivergence {
  /** Overall divergence (std dev across 4 scores, 0=consensus, 50=extreme conflict) */
  overall: number;

  /** Max - min score (Singapore: 94 - 22 = 72 point range) */
  maxRange: number;

  /** Pairwise differences (6 pairs: Western-Development, etc.) */
  pairwise: {
    western_development: number;
    western_ecological: number;
    western_indigenous: number;
    development_ecological: number;
    development_indigenous: number;
    ecological_indigenous: number;
  };

  /** Trend over last 12 months */
  trend: 'CONVERGING' | 'DIVERGING' | 'STABLE';
}

/**
 * Paradigm correlation tracking
 *
 * Validates research claims about paradigm relationships.
 * Expected: Western ↔ Development ~0.7-0.9, Development ↔ Ecological ~-0.6
 */
export interface ParadigmCorrelations {
  western_development: number;   // Expected ~0.7-0.9 (wealth correlation)
  western_ecological: number;    // Expected negative ~-0.4
  western_indigenous: number;    // Expected ~0.4-0.6
  development_ecological: number; // Expected negative ~-0.6
  development_indigenous: number; // Expected ~0.2-0.4
  ecological_indigenous: number;  // Expected ~0.5-0.7
}

/**
 * Outcome classification (optional, for Monte Carlo aggregation)
 *
 * Don't force single utopia/dystopia answer - show all 4 paradigm scores.
 * But for aggregation, classify how many paradigms say "utopia" vs "dystopia".
 */
export interface MultiParadigmOutcomeClassification {
  /** How many paradigms in utopia (≥80) */
  utopiasCount: number;

  /** How many paradigms in dystopia (≤30) */
  dystopiasCount: number;

  /** Some say utopia, some say dystopia (Singapore pattern) */
  contested: boolean;

  /** Human-readable summary */
  label: string;
  // Examples:
  // - "Development Utopia, Liberal Dystopia" (Singapore)
  // - "Ecological Dystopia, Liberal/Development Utopia" (Norway)
  // - "Multi-Paradigm Dystopia" (Yemen)
  // - "All-Four Utopia" (extremely rare, 0.5% of runs)
}

/**
 * Multi-Paradigm Dystopia-Utopia Index
 *
 * Complete state for 4-paradigm measurement system.
 */
export interface MultiParadigmDUI {
  /**
   * TIER 2A: High-Confidence Paradigms (drive simulation + report)
   */
  paradigmScores: {
    /**
     * Western Liberal (Freedom-Focused)
     *
     * Data: V-Dem 2024 (202 countries), Freedom House 2024-2025 (195 countries)
     * Confidence: HIGH
     * Drives: Democratic governance affects outcomes
     * Reports: Political freedom, civil liberties, economic freedom, rule of law
     *
     * Utopia: V-Dem ≥0.80, Freedom House ≥90/100 (~8 countries, 0.4% of world)
     * Dystopia: V-Dem <0.30, Freedom House <30/100
     */
    western: ParadigmScore & { drivesSimulation: true };

    /**
     * Development Needs (Survival-Focused)
     *
     * Data: UNDP HDI 2024 (193 countries), OPHI MPI 2024 (112 countries), WHO, FAO
     * Confidence: HIGH
     * Drives: Poverty → instability, health → productivity
     * Reports: Human development, poverty, food security, healthcare, education
     *
     * Utopia: HDI ≥0.900, MPI <0.005 (~25-30 countries, 10-12% of world)
     * Dystopia: HDI <0.550, MPI >0.300
     */
    development: ParadigmScore & { drivesSimulation: true };

    /**
     * Ecological Harmony (Sustainability-Focused)
     *
     * Data: Richardson et al. 2023 (9 planetary boundaries), Global Footprint Network 2024 (188 countries)
     * Confidence: MEDIUM-HIGH (±50% uncertainty on some boundaries)
     * Drives: Boundary transgression → crises
     * Reports: 9 boundaries, ecological footprint, climate stability, air quality
     *
     * Utopia: All 9 boundaries safe, footprint ≤1.5 gha (ZERO countries currently)
     * Dystopia: 6+ boundaries breached (current global state)
     */
    ecological: ParadigmScore & { drivesSimulation: true };
  };

  /**
   * TIER 2B: Reporting-Only Paradigms (diagnostic lens)
   */
  diagnosticLenses: {
    /**
     * Indigenous/Communitarian (Harmony-Focused)
     *
     * Data: Bhutan GNH 2024 (1 country, HIGH), WVS Wave 7 (80 countries, MEDIUM), derived (115 countries, LOW)
     * Confidence: LOW-MEDIUM (only 1 country has direct measurement)
     * Drives: NO - uses existing social cohesion mechanics
     * Reports: Community solidarity, cultural continuity, collective purpose
     *
     * Utopia: GNH ≥66%, social trust >60% (~1-2 countries)
     * Dystopia: Social trust <30%, cultural genocide, atomization
     *
     * Advocacy: Makes visible what we don't measure (199/200 countries lack GNH-equivalent)
     */
    indigenous: DiagnosticLens;
  };

  /**
   * Paradigm divergence (the diagnostic value!)
   */
  divergence: ParadigmDivergence;

  /**
   * Paradigm correlations (validates research claims)
   */
  correlations: ParadigmCorrelations;

  /**
   * Outcome classification (optional, for aggregation)
   */
  outcome: MultiParadigmOutcomeClassification;

  /**
   * Country-specific paradigm alignment
   *
   * Which paradigm does each country optimize for?
   * Examples: USA → Western, China → Development, Bhutan → Indigenous, Norway → Western+Development
   */
  dominantParadigm?: 'western' | 'development' | 'ecological' | 'indigenous' | 'contested';

  /**
   * Historical tracking (for paradigm shifts)
   *
   * Track 4 paradigm scores over time to detect:
   * - China's shift: Development-only → Development+Ecological (2012-2025)
   * - US communitarian collapse: Social trust 55% → 35% (1960-2024)
   * - Nordic maintenance: Can 3/4 paradigms be sustained? (Western+Development+Indigenous)
   */
  history: Array<{
    month: number;
    western: number;
    development: number;
    ecological: number;
    indigenous: number;
  }>;

  /**
   * Western Liberal Component Scores (Oct 21, 2025 - Goodhart's Law Fix)
   *
   * Geometric mean headline number obscures nuance. Expose components for analysis.
   *
   * Real story: "Electoral democracy 45%, civil liberties 8%, rule of law 30%"
   * NOT: "Western Liberal: 2/100" (compresses everything, invokes Goodhart)
   */
  westernLiberalComponents?: Array<{
    month: number;
    electoralDemocracy: number;  // 0-100
    civilLiberties: number;      // 0-100
    ruleOfLaw: number;           // 0-100
    economicFreedom: number;     // 0-100
  }>;
}

/**
 * Country-level Multi-Paradigm DUI
 *
 * For 30 countries with full government system integration, we track
 * country-specific paradigm scores. Others derive from regional patterns.
 */
export interface CountryParadigmScores {
  /** ISO 3166-1 alpha-3 country code (USA, CHN, DEU, etc.) */
  countryCode: string;

  /** Country name */
  countryName: string;

  /** 4 paradigm scores for this country */
  scores: {
    western: number;      // 0-100
    development: number;  // 0-100
    ecological: number;   // 0-100
    indigenous: number;   // 0-100
  };

  /** Paradigm divergence for this country */
  divergence: number;

  /** Dominant paradigm for this country */
  dominantParadigm: 'western' | 'development' | 'ecological' | 'indigenous' | 'contested';

  /** Data quality flags */
  dataQuality: {
    /** Does this country have government system data? (30 countries yes) */
    hasGovernmentData: boolean;

    /** Does this country have WVS proxy data? (80 countries yes) */
    hasWVSData: boolean;

    /** Overall data confidence for this country */
    confidence: ConfidenceLevel;
  };
}

