  const aggregated = await aggregateParadigms();

  // Test 1: hasGovernmentData flag
  console.log('Test 1: hasGovernmentData flag');
  console.log('-------------------------------');

  const governmentSystemCountries = new Set([
    'USA', 'CHN', 'IND', 'DEU', 'GBR', 'FRA', 'JPN', 'ITA', 'BRA', 'CAN',
