    17→const originalLog = console.log;
    18→const originalWarn = console.warn;
    19→console.log = () => {}; // Suppress simulation logs
    20→console.warn = () => {}; // Suppress warnings
    21→// Keep console.error for critical issues
    22→self.addEventListener('error', (e) => {
