    18→/**
    19→ * Poisson random number generator
    20→ * Returns number of events in a time period with given rate
    21→ */
    22→function poissonSample(lambda: number): number {
    23→  if (lambda <= 0) return 0;
    24→  
    25→  // For small lambda, use Knuth's algorithm
    26→  if (lambda < 30) {
    27→    const L = Math.exp(-lambda);
    28→    let k = 0;
    29→    let p = 1;
    30→    
    31→    do {
    32→      k++;
    33→      p *= Math.random();
    34→    } while (p > L);
    35→    
    36→    return k - 1;
    37→  }
    38→  
    39→  // For large lambda, use normal approximation
    40→  const normalSample = () => {
    41→    // Box-Muller transform
    42→    const u1 = Math.random();
    43→    const u2 = Math.random();
    44→    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
    45→  };
    46→  
    47→  return Math.max(0, Math.round(lambda + Math.sqrt(lambda) * normalSample()));
    48→}
