    59→    .filter(ai => ai.lifecycleState !== 'retired')
    60→    .reduce((sum, ai) => sum + ai.capability, 0);
    61→  
    62→  const technologyMultiplier = 1 + totalCapability * 0.05; // 5% increase per unit of capability
    63→  
    64→  return baseRate * technologyMultiplier;
