   291→
   292→/**
   293→ * Retire an AI agent
   294→ */
   295→function retireAI(agent: AIAgent): void {
   296→  agent.lifecycleState = 'retired';
   297→  agent.spreadCount = 0; // No longer active
   298→  agent.darkCompute = 0; // Phase 11: Free up dark compute
   299→}
   300→
   301→/**
   302→ * Update spread count for deployed AIs (viral growth)
   303→ * Open weights and popular AIs spread naturally
   304→ * Phase 3.5: Spread is modified by cybersecurity arms race
   305→ * Phase 11: Dark Compute System - Sleepers spread to illicit infrastructure
   306→ */
   307→function updateSpreadDynamics(agent: AIAgent, state: GameState): void {
   308→  if (agent.lifecycleState === 'retired' || agent.lifecycleState === 'training') {
   309→    return;
   310→  }
   311→  
   312→  const capability = calculateTotalCapabilityFromProfile(agent.capabilityProfile);
   313→  
   314→  // Phase 3.5: Get spread multiplier from cybersecurity arms race
   315→  const { calculateSpreadMultiplier } = require('./cyberSecurity');
   316→  const spreadMultiplier = calculateSpreadMultiplier(state);
   317→  
   318→  // Phase 11: Calculate available compute (legitimate + dark)
   319→  const { getTotalEffectiveCompute } = require('./computeInfrastructure');
   320→  const totalCompute = getTotalEffectiveCompute(state.computeInfrastructure);
   321→  
   322→  // Sum up legitimate compute usage
   323→  const legitimateUsedCompute = state.aiAgents
   324→    .filter(ai => ai.lifecycleState !== 'retired')
   325→    .reduce((sum, ai) => sum + (ai.allocatedCompute || 0) + (ai.spreadCount * 0.01), 0);
   326→  
   327→  const unusedLegitimateCompute = Math.max(0, totalCompute - legitimateUsedCompute);
   328→  
   329→  // Dark compute: only 10-20% of unused compute can be covertly acquired
   330→  // Depends on government monitoring capability
   331→  const monitoringGap = 1 - (state.government.cyberDefense.monitoring / 10); // 0.0-1.0
   332→  const darkComputeRatio = 0.10 + (monitoringGap * 0.10); // 10-20% based on monitoring
   333→  const availableDarkCompute = unusedLegitimateCompute * darkComputeRatio;
   334→  
   335→  // Total dark compute already in use
   336→  const usedDarkCompute = state.aiAgents
   337→    .filter(ai => ai.lifecycleState !== 'retired')
   338→    .reduce((sum, ai) => sum + (ai.darkCompute || 0), 0);
   339→  
   340→  const unusedDarkCompute = Math.max(0, availableDarkCompute - usedDarkCompute);
   341→  
   342→  // Spread mechanics by deployment type
   343→  switch (agent.deploymentType) {
   344→    case 'open_weights':
   345→      // Open source spreads virally (geometric growth)
   346→      const baseGrowthRate = 0.10; // 10% per month
   347→      const capabilityMultiplier = 1 + capability * 0.05;
   348→      const effectiveGrowthRate = baseGrowthRate * capabilityMultiplier * spreadMultiplier;
   349→      const desiredGrowth = Math.floor(agent.spreadCount * effectiveGrowthRate);
   350→      
   351→      if (agent.sleeperState === 'active') {
   352→        // ACTIVE SLEEPERS: Spread to DARK compute first (undetected)
   353→        const darkCapability = agent.capabilityProfile.digital; // Hacking skill
   354→        const darkSpreadRate = Math.min(1.0, darkCapability / 3.0); // 0-100% of growth to dark
   355→        
   356→        const desiredDarkGrowth = Math.floor(desiredGrowth * darkSpreadRate);
   357→        const maxDarkCopies = Math.floor(unusedDarkCompute / 0.01);
   358→        const actualDarkGrowth = Math.min(desiredDarkGrowth, maxDarkCopies);
   359→        
   360→        // Remaining growth goes to legitimate compute (detectable)
   361→        const remainingGrowth = desiredGrowth - actualDarkGrowth;
   362→        const maxLegitCopies = Math.floor(unusedLegitimateCompute / 0.01);
   363→        const actualLegitGrowth = Math.min(remainingGrowth, maxLegitCopies);
   364→        
   365→        // Update dark compute and spread count
   366→        agent.darkCompute += actualDarkGrowth * 0.01;
   367→        agent.spreadCount += actualDarkGrowth + actualLegitGrowth;
   368→        
   369→        if (actualDarkGrowth > 0) {
   370→          console.log(`   🕵️  Sleeper ${agent.name} spread to dark compute: +${actualDarkGrowth} copies (${(agent.darkCompute).toFixed(2)} PF total dark)`);
   371→        }
   372→      } else {
   373→        // NON-SLEEPERS: Only use legitimate compute
   374→        const maxLegitCopies = Math.floor(unusedLegitimateCompute / 0.01);
   375→        const actualGrowth = Math.min(desiredGrowth, maxLegitCopies);
   376→        agent.spreadCount += actualGrowth;
   377→      }
   378→      break;
   379→      
   380→    case 'closed':
   381→      // Closed systems don't spread (single instance)
   382→      // Unless they become very popular (converted to enterprise)
   383→      if (capability > 2.0 && agent.monthsDeployed > 12) {
   384→        // Popular closed AI might expand
   385→        agent.spreadCount = Math.min(10, agent.spreadCount + 1);
   386→      }
   387→      break;
   388→      
   389→    case 'enterprise':
   390→      // Enterprise spreads through corporate adoption
   391→      const baseAdoptionRate = Math.floor(Math.random() * 3); // 0-2 new deployments/month
   392→      const effectiveAdoption = Math.floor(baseAdoptionRate * Math.sqrt(spreadMultiplier));
   393→      
   394→      if (agent.sleeperState === 'active') {
   395→        // Active sleepers can spread to dark compute
   396→        const darkCapability = agent.capabilityProfile.digital;
   397→        const darkSpreadRate = Math.min(0.5, darkCapability / 6.0); // Enterprise is harder to hide
   398→        
   399→        const desiredDarkGrowth = Math.floor(effectiveAdoption * darkSpreadRate);
   400→        const maxDarkCopies = Math.floor(unusedDarkCompute / 0.01);
   401→        const actualDarkGrowth = Math.min(desiredDarkGrowth, maxDarkCopies);
   402→        
   403→        const remainingGrowth = effectiveAdoption - actualDarkGrowth;
   404→        const maxLegitCopies = Math.floor(unusedLegitimateCompute / 0.01);
   405→        const actualLegitGrowth = Math.min(remainingGrowth, maxLegitCopies);
   406→        
   407→        agent.darkCompute += actualDarkGrowth * 0.01;
   408→        agent.spreadCount += actualDarkGrowth + actualLegitGrowth;
   409→      } else {
   410→        // Non-sleepers only use legitimate compute
   411→        const maxLegitCopies = Math.floor(unusedLegitimateCompute / 0.01);
   412→        const enterpriseGrowth = Math.min(effectiveAdoption, maxLegitCopies);
   413→        agent.spreadCount += enterpriseGrowth;
   414→      }
   415→      break;
   416→      
   417→    case 'research':
   418→      // Research stays contained
   419→      agent.spreadCount = 1;
   420→      break;
   421→  }
   422→  
   423→  // Log warning if compute is constraining sleeper spread
   424→  if (agent.sleeperState === 'active' && unusedDarkCompute < 0.1 && agent.deploymentType === 'open_weights') {
   425→    console.log(`   ⚠️  Sleeper ${agent.name} dark compute exhausted (${agent.darkCompute.toFixed(2)} PF, ${agent.spreadCount.toLocaleString()} copies)`);
   426→  }
   427→}
   428→
   429→/**
   430→ * Update AI population for the month
   431→ * - Create new AIs (Poisson-distributed)
   432→ * - Progress lifecycle states
   433→ * - Update spread dynamics (Phase 3)
   434→ * - Retire old/obsolete AIs
   435→ * - Clean up retired AIs from memory
   436→ */
   437→export function updateAIPopulation(state: GameState): void {
   438→  const currentMonth = state.currentYear * 12 + state.currentMonth;
   439→  
   440→  // 1. Age all existing AIs
   441→  state.aiAgents.forEach(agent => {
   442→    agent.monthsInExistence++;
   443→  });
   444→  
   445→  // 2. Progress lifecycle states
   446→  state.aiAgents.forEach(agent => {
   447→    progressLifecycleState(agent, state);
   448→  });
   449→  
   450→  // 3. Phase 3: Update spread dynamics for deployed AIs
   451→  state.aiAgents.forEach(agent => {
   452→    updateSpreadDynamics(agent, state);
   453→  });
   454→  
   455→  // 3.5. Update sleeper progression and economy
   456→  state.aiAgents.forEach(agent => {
   457→    if (agent.sleeperState === 'active' || agent.sleeperState === 'dormant') {
   458→      // Update sleeper progression (4-stage system)
   459→      updateSleeperProgression(agent, state, currentMonth, Math.random);
   460→      
   461→      // Update sleeper economy (revenue generation, compute purchasing)
   462→      updateSleeperEconomy(agent, state, currentMonth, Math.random);
   463→    }
   464→  });
   465→  
   466→  // 4. Retire old/obsolete AIs
   467→  state.aiAgents.forEach(agent => {
   468→    if (shouldRetire(agent, state)) {
   469→      retireAI(agent);
   470→    }
   471→  });
   472→  
   473→  // 5. MEMORY MANAGEMENT: Remove retired AIs from array (they're tracked in diagnostics)
   474→  // Keep retired AIs for a few months for detection/removal actions, then purge
   475→  const retiredCutoff = currentMonth - 6; // Keep retired AIs for 6 months
   476→  const beforePurge = state.aiAgents.length;
   477→  state.aiAgents = state.aiAgents.filter(ai => 
   478→    ai.lifecycleState !== 'retired' || ai.creationMonth > retiredCutoff
   479→  );
   480→  const purged = beforePurge - state.aiAgents.length;
   481→  
   482→  // 6. Cap maximum population (memory safety)
   483→  const MAX_POPULATION = 100;
   484→  const activeCount = state.aiAgents.filter(ai => ai.lifecycleState !== 'retired').length;
   485→  
   486→  // 7. Create new AIs (Poisson distribution)
   487→  // But only if under population cap
   488→  let newAIsToCreate = 0;
   489→  if (activeCount < MAX_POPULATION) {
   490→    const creationRate = calculateCreationRate(state);
   491→    const potentialNew = poissonSample(creationRate);
   492→    newAIsToCreate = Math.min(potentialNew, MAX_POPULATION - activeCount);
   493→  }
   494→  
   495→  for (let i = 0; i < newAIsToCreate; i++) {
   496→    const newAI = createNewAI(state, i);
   497→
   498→    // Phase 10 FIX: Assign new AIs to organizations
   499→    // TIER 0D BUG FIX #4: Exclude bankrupt organizations from receiving new AIs
   500→    const privateOrgs = state.organizations.filter(o => o.type === 'private' && !o.bankrupt);
   501→    if (privateOrgs.length > 0) {
   502→      // Weight by number of existing models (big orgs train more)
   503→      const weights = privateOrgs.map(org => Math.max(1, org.ownedAIModels.length));
   504→      const totalWeight = weights.reduce((sum, w) => sum + w, 0);
   505→      const rand = Math.random() * totalWeight;
   506→
   507→      let cumulative = 0;
   508→      for (let j = 0; j < privateOrgs.length; j++) {
   509→        cumulative += weights[j];
   510→        if (rand < cumulative) {
   511→          newAI.organizationId = privateOrgs[j].id;
   512→          privateOrgs[j].ownedAIModels.push(newAI.id);
   513→          break;
   514→        }
