     1→/**
     2→ * TIER 2 Phase 4: Proactive Sleeper Agent Detection
     3→ *
     4→ * Research Foundation:
     5→ * - gaming-sleeper-detection_20251017.md (initial research)
     6→ * - gaming-sleeper-detection-critique_20251017.md (research-skeptic validation)
     7→ *
     8→ * REVISED PARAMETERS (Post Research-Skeptic Review):
     9→ * - Neural activation probes: 35% on natural deception (down from 70%, artificial backdoors 99%)
    10→ * - Chain of thought monitoring: 30% baseline (down from 45%), declining -15%/year
    11→ * - Combined proactive: 50% baseline 2024 (down from 80%), declining to 20-25% by 2027
    12→ * - False positives: 8%
    13→ * - Continuous overhead: 10%
    14→ * - Human review: 1.5% FTE per 100K interactions (up from 0.3%, 5x increase)
    15→ *
    16→ * KEY INSIGHT: Detection window is FRAGILE and TEMPORARY (2024-2027)
    17→ * CoT monitoring becomes ineffective as models learn to hide reasoning.
    18→ * Neural probes uncertain on naturally emergent deception (vs artificial backdoors).
    19→ *
    20→ * Methods:
    21→ * 1. Neural activation probes (latent deception signatures)
    22→ * 2. Chain of thought monitoring (inspect reasoning traces)
    23→ * 3. Human review (expert analysis of flags)
    24→ */
    25→
    26→import { GameState, AIAgent, GameEvent } from '@/types/game';
    27→
    28→/**
    29→ * Sleeper detection scenario types
    30→ */
    31→export type SleeperDetectionScenario = 'optimistic' | 'baseline' | 'pessimistic';
    32→
    33→/**
    34→ * Proactive sleeper detection state (added to GameState)
    35→ */
    36→export interface ProactiveSleeperDetectionState {
    37→  // Scenario configuration
    38→  scenario: SleeperDetectionScenario;
    39→
    40→  // Detection rates (scenario-dependent, time-decaying)
    41→  neuralProbeRate: number;          // Neural activation probe effectiveness
    42→  cotMonitoringRate: number;        // Chain of thought monitoring effectiveness
    43→  combinedDetectionRate: number;    // Overall proactive detection
    44→
    45→  falsePositiveRate: number;        // False positive rate
    46→
    47→  // Detected sleepers this run
    48→  sleepersDetected: string[];       // AI IDs caught as sleepers
    49→  falsePositives: string[];         // AI IDs falsely accused
    50→
    51→  // Temporal degradation
    52→  yearsSinceActivation: number;     // Years since detection enabled
    53→  cotDegradationFactor: number;     // CoT effectiveness multiplier (decays fast)
    54→  probeDegradationFactor: number;   // Probe effectiveness multiplier (decays slower)
