   302→  const investigationWorkload = (detections + falsePositives) * 0.005; // 0.5% FTE per investigation
   303→
   304→  return baseWorkload + investigationWorkload;
   305→}
   306→
   307→/**
   308→ * Process proactive sleeper detection for all AIs
   309→ *
   310→ * Returns events and updates detection state
   311→ */
   312→export function processProactiveSleeperDetection(
   313→  state: GameState,
   314→  rng: () => number
   315→): GameEvent[] {
   316→  const events: GameEvent[] = [];
   317→
   318→  // Check if sleeper detection is initialized
