   353→        impactedAgents: [ai.id]
   354→      });
   355→
   356→      // Mark AI as detected (affects trust, triggers removal)
   357→      ai.detectedMisaligned = true;
   358→
   359→      // CRITICAL: Detected sleeper damages trust in ALL AI
