   389→
   390→  // Calculate human review workload
   391→  detectionState.humanReviewWorkload = calculateSleeperReviewWorkload(
   392→    detectionState.sleepersDetected.length,
   393→    detectionState.falsePositives.length,
   394→    state
   395→  );
   396→
   397→  // Log detection statistics periodically
