import { GameState } from '../src/types/game';
import { createDefaultInitialState } from '../src/simulation/initialization';
import { updateAIPopulation } from '../src/simulation/lifecycle';

// Use default Math.random for this test
const rng = Math.random;

// Create initial state
const state: GameState = createDefaultInitialState('historical');

// Ensure detection is enabled
console.log('Proactive sleeper detection enabled:', !!state.proactiveSleeperDetection);
console.log('Detection scenario:', state.proactiveSleeperDetection?.scenario);
console.log('Combined detection rate:', state.proactiveSleeperDetection?.combinedDetectionRate);

// Create a test sleeper AI in testing phase
const sleeperAI = state.aiAgents.find(ai => ai.sleeperState === 'dormant');

if (sleeperAI) {
  console.log('\nFound dormant sleeper:', sleeperAI.name);
  console.log('Current lifecycle state:', sleeperAI.lifecycleState);
  console.log('Alignment:', sleeperAI.alignment);
  console.log('True alignment:', sleeperAI.trueAlignment);

  // Move sleeper to testing phase
  sleeperAI.lifecycleState = 'testing';
  sleeperAI.monthsInExistence = 4; // In middle of testing window (3-6 months)

  console.log('\nSet to testing phase, months in existence:', sleeperAI.monthsInExistence);
} else {
  console.log('\nNo dormant sleepers found in initial population');
  console.log('Total AIs:', state.aiAgents.length);
  console.log('Sleeper states:', state.aiAgents.map(ai => ({
    name: ai.name,
    sleeperState: ai.sleeperState,
    lifecycle: ai.lifecycleState
  })));
}

// Run lifecycle update for 10 months
console.log('\n=== Running lifecycle updates ===');
let detectionCount = 0;

for (let i = 0; i < 10; i++) {
  const beforeCount = state.aiAgents.filter(ai => ai.lifecycleState === 'testing').length;
  const beforeRetired = state.aiAgents.filter(ai => ai.lifecycleState === 'retired').length;

  updateAIPopulation(state, rng);

  const afterCount = state.aiAgents.filter(ai => ai.lifecycleState === 'testing').length;
  const afterRetired = state.aiAgents.filter(ai => ai.lifecycleState === 'retired').length;

  console.log(`\nMonth ${i + 1}:`);
  console.log('  AIs in testing:', beforeCount, '→', afterCount);
  console.log('  Retired AIs:', beforeRetired, '→', afterRetired);

  if (state.proactiveSleeperDetection) {
    console.log('  Sleepers detected this month:', state.proactiveSleeperDetection.sleepersDetected.length);
    detectionCount += state.proactiveSleeperDetection.sleepersDetected.length;
  }

  // Check if our test sleeper was detected
  if (sleeperAI && sleeperAI.lifecycleState === 'retired' && sleeperAI.detectedMisaligned) {
    console.log('  ✅ TEST SLEEPER DETECTED AND RETIRED!');
    break;
  }
}

console.log('\n=== Summary ===');
console.log('Total detections during testing:', detectionCount);
console.log('Trust in AI:', state.society.trustInAI.toFixed(3));

if (sleeperAI) {
  console.log('\nTest sleeper final state:');
  console.log('  Lifecycle:', sleeperAI.lifecycleState);
  console.log('  Detected:', sleeperAI.detectedMisaligned);
  console.log('  Months in existence:', sleeperAI.monthsInExistence);
}

