/**
 * Multi-run test to verify sleeper detection during testing phase
 *
 * Runs the same scenario 100 times to see detection rate
 */

import { GameState } from '../src/types/game';
import { createDefaultInitialState } from '../src/simulation/initialization';
import { updateAIPopulation } from '../src/simulation/lifecycle';

console.log('=== Testing Sleeper Detection During Testing Phase (100 runs) ===\n');

let totalRuns = 100;
let detectionCount = 0;
let deployedCount = 0;

for (let run = 0; run < totalRuns; run++) {
  // Create initial state
  const state: GameState = createDefaultInitialState('historical');

  // Find/create a test sleeper
  let sleeperAI = state.aiAgents[0];

  // Convert to dormant sleeper in testing phase
  sleeperAI.sleeperState = 'dormant';
  sleeperAI.lifecycleState = 'testing';
  sleeperAI.monthsInExistence = 4;
  sleeperAI.alignment = 0.35;
  sleeperAI.trueAlignment = 0.25;
  sleeperAI.deceptionSkill = 0.6;

  // Run lifecycle updates until sleeper leaves testing phase
  for (let month = 0; month < 10; month++) {
    updateAIPopulation(state, Math.random);

    // Check if detected and retired
    if (sleeperAI.lifecycleState === 'retired' && sleeperAI.detectedMisaligned) {
      detectionCount++;
      break;
    }

    // Check if deployed (escaped detection)
    if (sleeperAI.lifecycleState === 'deployed_closed' || sleeperAI.lifecycleState === 'deployed_open') {
      deployedCount++;
      break;
    }
  }

  if ((run + 1) % 20 === 0) {
    process.stdout.write('.');
  }
}

console.log('\n\n=== Results ===');
console.log(`Total runs: ${totalRuns}`);
console.log(`Detected during testing: ${detectionCount} (${(detectionCount / totalRuns * 100).toFixed(1)}%)`);
console.log(`Deployed (escaped): ${deployedCount} (${(deployedCount / totalRuns * 100).toFixed(1)}%)`);
console.log(`Other (still in testing): ${totalRuns - detectionCount - deployedCount}`);

console.log('\n=== Analysis ===');
console.log(`Expected detection rate: ~35-50% (baseline minus deception penalty)`);
console.log(`Actual detection rate: ${(detectionCount / totalRuns * 100).toFixed(1)}%`);

if (detectionCount > 0) {
  console.log('\n✅ Detection during testing phase is WORKING!');
} else {
  console.log('\n❌ Detection during testing phase is NOT working!');
}

