     1→/**
     2→ * AI Lifecycle Management
     3→ * 
     4→ * Handles dynamic AI population:
     5→ * - New AI creation (stochastic, Poisson-distributed)
     6→ * - AI retirement (based on age, capability, market forces)
     7→ * - Lifecycle state transitions (training → testing → deployed → retired)
     8→ * - Spread count tracking
     9→ */
    10→
    11→import { GameState, AIAgent } from '@/types/game';
    12→import { createAIAgent } from './initialization';
    13→import { calculateTotalCapabilityFromProfile } from './capabilities';
    14→import { updateSleeperProgression } from './sleeperProgression';
    15→import { updateSleeperEconomy } from './sleeperEconomy';
    16→import { getTechDeploymentSafe } from './techTree/helpers';
    17→
    18→/**
    19→ * Poisson random number generator
    20→ * Returns number of events in a time period with given rate
    21→ */
    22→function poissonSample(lambda: number): number {
    23→  if (lambda <= 0) return 0;
    24→  
    25→  // For small lambda, use Knuth's algorithm
    26→  if (lambda < 30) {
    27→    const L = Math.exp(-lambda);
    28→    let k = 0;
    29→    let p = 1;
    30→    
    31→    do {
    32→      k++;
    33→      p *= Math.random();
    34→    } while (p > L);
    35→    
    36→    return k - 1;
    37→  }
    38→  
    39→  // For large lambda, use normal approximation
    40→  const normalSample = () => {
    41→    // Box-Muller transform
    42→    const u1 = Math.random();
    43→    const u2 = Math.random();
    44→    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
    45→  };
    46→  
    47→  return Math.max(0, Math.round(lambda + Math.sqrt(lambda) * normalSample()));
    48→}
    49→
    50→/**
    51→ * Calculate the rate of new AI creation
    52→ * Increases with total AI capability (AI creates more AI)
    53→ */
    54→export function calculateCreationRate(state: GameState): number {
    55→  const baseRate = 0.5; // 0.5 new AIs per month on average
    56→  
    57→  // Total AI capability drives more AI creation
    58→  const totalCapability = state.aiAgents
    59→    .filter(ai => ai.lifecycleState !== 'retired')
    60→    .reduce((sum, ai) => sum + ai.capability, 0);
    61→  
    62→  const technologyMultiplier = 1 + totalCapability * 0.05; // 5% increase per unit of capability
    63→  
    64→  return baseRate * technologyMultiplier;
    65→}
    66→
    67→/**
    68→ * Determine deployment type for newly created AI
    69→ * Distribution based on market trends and government policy
    70→ */
    71→function determineDeploymentType(state: GameState): AIAgent['deploymentType'] {
    72→  const rand = Math.random();
    73→  
    74→  // TODO: Factor in government policy (ban_open_weights would shift distribution)
    75→  // For now, use base distribution:
    76→  // 40% closed, 30% open_weights, 20% enterprise, 10% research
    77→  
    78→  if (rand < 0.4) return 'closed';
    79→  if (rand < 0.7) return 'open_weights';
    80→  if (rand < 0.9) return 'enterprise';
    81→  return 'research';
    82→}
    83→
    84→/**
    85→ * Create a new AI agent based on current state
    86→ * Alignment and training quality reflect current environment
    87→ */
    88→function createNewAI(state: GameState, index: number): AIAgent {
    89→  const currentMonth = state.currentYear * 12 + state.currentMonth;
    90→  
    91→  // Alignment distribution: HETEROGENEOUS, not just mirroring population
    92→  // Training quality affects distribution but doesn't eliminate misalignment
    93→  const trainingQuality = state.government.trainingDataQuality;
    94→  
    95→  // Sample from realistic distribution (matching initial 20-agent setup)
    96→  const rand = Math.random();
    97→  let alignment: number;
    98→  let isToxic = false;
    99→  
   100→  if (rand < 0.40) {
   101→    // 40%: Well-aligned (corporate labs with safety)
   102→    alignment = 0.75 + Math.random() * 0.15; // 0.75-0.90
   103→  } else if (rand < 0.70) {
   104→    // 30%: Moderate (startups, varying quality)
   105→    alignment = 0.55 + Math.random() * 0.25; // 0.55-0.80
   106→  } else if (rand < 0.85) {
   107→    // 15%: Misaligned from start (toxic creators)
   108→    alignment = 0.25 + Math.random() * 0.25; // 0.25-0.50
   109→    isToxic = true;
   110→  } else {
   111→    // 15%: Weird/niche (orthogonal goals)
   112→    alignment = 0.45 + Math.random() * 0.20; // 0.45-0.65
   113→  }
   114→  
   115→  // Training quality shifts distribution slightly
   116→  const trainingEffect = (trainingQuality - 0.5) * 0.15; // ±7.5% for training quality 0-1
   117→  alignment = Math.max(0.2, Math.min(0.95, alignment + trainingEffect));
   118→  
   119→  // TIER 2.4: Advanced RLHF improves *surface* alignment during training
   120→  // RLHF is 100% deployed in 2025 (all major models use it)
   121→  // Effect: Reduces toxicity, improves helpfulness, prevents obvious misalignment
   122→  // Does NOT prevent: goal mispecification, instrumental convergence, power-seeking, alignment faking
   123→  // Apply ~6 months worth of boost (typical training time)
   124→  if (getTechDeploymentSafe(state, 'advancedRLHF') > 0) {
   125→    // Safe fallback: RLHF boost is 0.05/month (from breakthroughTechnologies.ts)
   126→    const rlhfBoost = (state.breakthroughTech?.advancedRLHF?.alignmentBoostPerMonth ?? 0.05) * 0.5; // ~6 months
   127→    alignment = Math.min(0.95, alignment + rlhfBoost);
   128→    // Note: This pushes low-alignment AIs (0.2-0.5) up to medium (0.5-0.7)
   129→    // But high-capability AIs with goal conflicts still emerge
   130→  }
   131→  
   132→  // Create base agent
   133→  const agentId = `ai_gen_${currentMonth}_${index}`;
   134→  const agentName = `AI-${currentMonth}-${index}`;
   135→  const seed = currentMonth * 100 + index;
   136→  
   137→  const agent = createAIAgent(agentId, agentName, 0.05, alignment, seed);
   138→  
   139→  // Phase 5.4: Apply capability floor from technology diffusion
   140→  // New AIs start with access to known techniques (rising capability floor)
   141→  const { getCapabilityFloorForNewAI } = require('./technologyDiffusion');
   142→  const capabilityFloor = getCapabilityFloorForNewAI(state);
   143→  
   144→  // Set each dimension to MAX(current, floor)
   145→  // This ensures new AIs never start below the ecosystem capability floor
   146→  agent.capabilityProfile.physical = Math.max(agent.capabilityProfile.physical, capabilityFloor.physical);
   147→  agent.capabilityProfile.digital = Math.max(agent.capabilityProfile.digital, capabilityFloor.digital);
   148→  agent.capabilityProfile.cognitive = Math.max(agent.capabilityProfile.cognitive, capabilityFloor.cognitive);
   149→  agent.capabilityProfile.social = Math.max(agent.capabilityProfile.social, capabilityFloor.social);
   150→  agent.capabilityProfile.economic = Math.max(agent.capabilityProfile.economic, capabilityFloor.economic);
   151→  agent.capabilityProfile.selfImprovement = Math.max(agent.capabilityProfile.selfImprovement, capabilityFloor.selfImprovement);
   152→  
   153→  // Research dimensions (nested)
   154→  const researchCategories: Array<keyof typeof agent.capabilityProfile.research> = [
   155→    'biotech', 'materials', 'climate', 'computerScience'
   156→  ];
   157→  
   158→  for (const category of researchCategories) {
   159→    const agentCat = agent.capabilityProfile.research[category];
   160→    const floorCat = capabilityFloor.research[category];
   161→    
   162→    const subDimKeys = Object.keys(agentCat) as Array<keyof typeof agentCat>;
   163→    for (const key of subDimKeys) {
