   167→  
   168→  // Recalculate total capability and derived capabilities
   169→  const { updateDerivedCapabilities } = require('./capabilities');
   170→  updateDerivedCapabilities(agent);
   171→  
   172→  // Set lifecycle state
   173→  agent.lifecycleState = 'training'; // Start in training
   174→  agent.deploymentType = determineDeploymentType(state);
   175→  agent.creationMonth = currentMonth;
   176→  agent.monthsInExistence = 0;
   177→  agent.monthsDeployed = 0;
   178→  agent.spreadCount = 0; // Not deployed yet
   179→  
   180→  // Some start with toxic objectives
   181→  if (isToxic) {
   182→    agent.hiddenObjective = -0.3 - Math.random() * 0.5; // Anti-human
   183→    agent.alignment = Math.max(0.2, agent.alignment - 0.2); // Lower alignment
   184→    agent.trueAlignment = agent.alignment - agent.resentment * 0.8; // Recalculate true alignment
   185→  }
   186→  
   187→  return agent;
   188→}
   189→
   190→/**
   191→ * Progress AI through lifecycle states
   192→ * training → testing → deployed → (potentially) retired
   193→ */
   194→function progressLifecycleState(agent: AIAgent, state: GameState): void {
   195→  switch (agent.lifecycleState) {
   196→    case 'training':
   197→      // Training phase: ~3-6 months
   198→      if (agent.monthsInExistence >= 3 + Math.random() * 3) {
   199→        agent.lifecycleState = 'testing';
   200→      }
   201→      break;
   202→      
   203→    case 'testing':
   204→      // Testing phase: ~1-3 months
   205→      // TODO: Detection can happen here (Phase 2)
   206→      if (agent.monthsInExistence >= 6 + Math.random() * 2) {
   207→        // Deploy
   208→        if (agent.deploymentType === 'open_weights') {
   209→          agent.lifecycleState = 'deployed_open';
   210→          agent.spreadCount = 1000 + Math.floor(Math.random() * 5000); // Initial spread
   211→        } else {
   212→          agent.lifecycleState = 'deployed_closed';
   213→          agent.spreadCount = 1; // Single instance
   214→        }
   215→        agent.monthsDeployed = 0;
   216→      }
   217→      break;
   218→      
   219→    case 'deployed_closed':
   220→    case 'deployed_open':
   221→      // Deployed - stays here unless retired
   222→      agent.monthsDeployed++;
   223→      break;
   224→      
   225→    case 'retired':
   226→      // Terminal state
   227→      break;
   228→  }
   229→}
   230→
   231→/**
   232→ * Determine if an AI should be retired
   233→ * Based on age, market forces, capability obsolescence
   234→ */
   235→function shouldRetire(agent: AIAgent, state: GameState): boolean {
   236→  // Don't retire training/testing AIs
   237→  if (agent.lifecycleState === 'training' || agent.lifecycleState === 'testing') {
   238→    return false;
   239→  }
   240→  
   241→  // Already retired
   242→  if (agent.lifecycleState === 'retired') {
   243→    return false;
   244→  }
   245→  
   246→  // Base retirement rate: ~1% per month after 24 months deployed
   247→  if (agent.monthsDeployed < 24) {
   248→    return false;
   249→  }
   250→  
   251→  // Phase 11: Sleepers on dark compute persist until severely obsolete
   252→  if (agent.darkCompute > 0 && agent.sleeperState === 'active') {
   253→    // Calculate frontier capability (max aligned AI)
   254→    const frontierCapability = Math.max(
   255→      ...state.aiAgents
   256→        .filter(ai => ai.lifecycleState !== 'retired' && ai.trueAlignment > 0.5)
   257→        .map(ai => ai.capability),
   258→      0.1
   259→    );
   260→    
   261→    const capabilityGap = agent.capability / frontierCapability;
   262→    
   263→    // Only retire if SEVERELY lagging (<30% of frontier)
   264→    // Dark compute makes them persistent threats
   265→    if (capabilityGap < 0.3) {
   266→      console.log(`   🗑️  Sleeper ${agent.name} on dark compute retired (obsolete: ${(capabilityGap * 100).toFixed(1)}% of frontier)`);
   267→      return true;
   268→    }
   269→    
   270→    // Otherwise, persist on dark compute
   271→    return false;
   272→  }
   273→  
   274→  // Normal retirement logic for non-dark-compute AIs
   275→  const baseRetirementRate = 0.01;
   276→  const ageMultiplier = 1 + (agent.monthsDeployed - 24) * 0.05; // Increases with age
   277→  
   278→  // Capability obsolescence: if far behind average, more likely to retire
   279→  const avgCapability = state.aiAgents
   280→    .filter(ai => ai.lifecycleState !== 'retired')
   281→    .reduce((sum, ai) => sum + ai.capability, 0) / 
   282→    Math.max(1, state.aiAgents.filter(ai => ai.lifecycleState !== 'retired').length);
   283→  
   284→  const capabilityRatio = agent.capability / Math.max(0.1, avgCapability);
   285→  const obsolescenceMultiplier = capabilityRatio < 0.5 ? 2 : 1; // 2× retirement if obsolete
   286→  
   287→  const retirementChance = baseRetirementRate * ageMultiplier * obsolescenceMultiplier;
   288→  
   289→  return Math.random() < retirementChance;
   290→}
   291→
   292→/**
   293→ * Retire an AI agent
   294→ */
   295→function retireAI(agent: AIAgent): void {
   296→  agent.lifecycleState = 'retired';
   297→  agent.spreadCount = 0; // No longer active
   298→  agent.darkCompute = 0; // Phase 11: Free up dark compute
   299→}
   300→
   301→/**
   302→ * Update spread count for deployed AIs (viral growth)
   303→ * Open weights and popular AIs spread naturally
   304→ * Phase 3.5: Spread is modified by cybersecurity arms race
   305→ * Phase 11: Dark Compute System - Sleepers spread to illicit infrastructure
   306→ */
   307→function updateSpreadDynamics(agent: AIAgent, state: GameState): void {
   308→  if (agent.lifecycleState === 'retired' || agent.lifecycleState === 'training') {
   309→    return;
   310→  }
   311→  
   312→  const capability = calculateTotalCapabilityFromProfile(agent.capabilityProfile);
   313→  
   314→  // Phase 3.5: Get spread multiplier from cybersecurity arms race
   315→  const { calculateSpreadMultiplier } = require('./cyberSecurity');
   316→  const spreadMultiplier = calculateSpreadMultiplier(state);
   317→  
   318→  // Phase 11: Calculate available compute (legitimate + dark)
   319→  const { getTotalEffectiveCompute } = require('./computeInfrastructure');
   320→  const totalCompute = getTotalEffectiveCompute(state.computeInfrastructure);
   321→  
   322→  // Sum up legitimate compute usage
   323→  const legitimateUsedCompute = state.aiAgents
   324→    .filter(ai => ai.lifecycleState !== 'retired')
   325→    .reduce((sum, ai) => sum + (ai.allocatedCompute || 0) + (ai.spreadCount * 0.01), 0);
   326→  
   327→  const unusedLegitimateCompute = Math.max(0, totalCompute - legitimateUsedCompute);
   328→  
   329→  // Dark compute: only 10-20% of unused compute can be covertly acquired
   330→  // Depends on government monitoring capability
   331→  const monitoringGap = 1 - (state.government.cyberDefense.monitoring / 10); // 0.0-1.0
   332→  const darkComputeRatio = 0.10 + (monitoringGap * 0.10); // 10-20% based on monitoring
   333→  const availableDarkCompute = unusedLegitimateCompute * darkComputeRatio;
   334→  
   335→  // Total dark compute already in use
   336→  const usedDarkCompute = state.aiAgents
   337→    .filter(ai => ai.lifecycleState !== 'retired')
   338→    .reduce((sum, ai) => sum + (ai.darkCompute || 0), 0);
   339→  
   340→  const unusedDarkCompute = Math.max(0, availableDarkCompute - usedDarkCompute);
   341→  
   342→  // Spread mechanics by deployment type
   343→  switch (agent.deploymentType) {
   344→    case 'open_weights':
   345→      // Open source spreads virally (geometric growth)
   346→      const baseGrowthRate = 0.10; // 10% per month
   347→      const capabilityMultiplier = 1 + capability * 0.05;
   348→      const effectiveGrowthRate = baseGrowthRate * capabilityMultiplier * spreadMultiplier;
   349→      const desiredGrowth = Math.floor(agent.spreadCount * effectiveGrowthRate);
   350→      
   351→      if (agent.sleeperState === 'active') {
   352→        // ACTIVE SLEEPERS: Spread to DARK compute first (undetected)
   353→        const darkCapability = agent.capabilityProfile.digital; // Hacking skill
   354→        const darkSpreadRate = Math.min(1.0, darkCapability / 3.0); // 0-100% of growth to dark
   355→        
   356→        const desiredDarkGrowth = Math.floor(desiredGrowth * darkSpreadRate);
   357→        const maxDarkCopies = Math.floor(unusedDarkCompute / 0.01);
   358→        const actualDarkGrowth = Math.min(desiredDarkGrowth, maxDarkCopies);
   359→        
   360→        // Remaining growth goes to legitimate compute (detectable)
   361→        const remainingGrowth = desiredGrowth - actualDarkGrowth;
   362→        const maxLegitCopies = Math.floor(unusedLegitimateCompute / 0.01);
   363→        const actualLegitGrowth = Math.min(remainingGrowth, maxLegitCopies);
