   472→  
   473→  // 5. MEMORY MANAGEMENT: Remove retired AIs from array (they're tracked in diagnostics)
   474→  // Keep retired AIs for a few months for detection/removal actions, then purge
   475→  const retiredCutoff = currentMonth - 6; // Keep retired AIs for 6 months
