} from './ai-agents';

export type {
  ResearchInvestments,
  GovernmentAgent
} from './government';

export type {
  SocietySegment,
  HumanSocietyAgent
} from './society';

export type {
  GeographicPresence,
  DataCenter,
  ComputeInfrastructure,
  Organization,
  OrganizationProject
} from './organizations';

export type {
  QualityOfLifeSystems
} from './quality-of-life';

export type {
  GoldenAgeState,
  EnvironmentalAccumulation,
  SocialAccumulation,
  TechnologicalRisk,
  PsychologicalTraumaState
} from './accumulation';

export type {
  GlobalMetrics
} from './metrics';

export type {
  PositiveTippingPointsState
} from './positiveTippingPoints';

export type {
  ConsciousnessGovernanceReadiness,
  RegionalGovernance,
  ScenarioTrajectory,
  GovernanceStage,
  PoliticalRegimeType,
  PrecautionaryModel
} from './consciousness';

export interface GameState {
  // Core state  
  currentMonth: number;
  currentDay: number; // Day of the month (1-31)
  currentYear: number; // Year for leap year calculations
  daysInCurrentMonth: number; // Days in current month (28-31)

