     1→/**
     2→ * Regulation government actions
     3→ *
     4→ * Actions related to AI regulation including:
     5→ * - Large company regulation
     6→ * - Compute threshold regulation
     7→ * - Capability ceiling regulation
     8→ * - Compute governance
     9→ * - Research publishing restrictions
    10→ * - Employee mobility limits
    11→ * - Reverse engineering bans
    12→ */
    13→
    14→import { GameState } from '@/types/game';
    15→import { ActionResult } from '@/simulation/agents/types';
    16→import { CategorizedGovernmentAction } from '../core/types';
    17→import { calculateRegulationStructuralEffects } from '@/simulation/calculations';
    18→
    19→let eventIdCounter = 0;
    20→const generateUniqueId = (prefix: string): string => {
    21→  eventIdCounter += 1;
    22→  return `${prefix}_${Date.now()}_${eventIdCounter}`;
    23→};
    24→
    25→/**
    26→ * Regulate Large AI Companies
    27→ * Popular but small labs escape
    28→ */
    29→const regulateLargeCompanies: CategorizedGovernmentAction = {
    30→  id: 'regulate_large_companies',
    31→  name: 'Regulate Large AI Companies',
    32→  description: 'Mandate safety standards for companies with significant revenue (popular, but small labs escape)',
    33→  agentType: 'government',
    34→  category: 'regulation',
    35→  energyCost: 2,
    36→
    37→  canExecute: (state: GameState): boolean => {
    38→    return state.government.controlDesire > 0.4 &&
    39→           state.government.structuralChoices.regulationType === 'none';
    40→  },
    41→
    42→  execute: (state: GameState, agentId?: string, random = Math.random): ActionResult => {
    43→    // Set regulation type
    44→    state.government.structuralChoices.regulationType = 'large_companies';
    45→
    46→    const effects = calculateRegulationStructuralEffects('large_companies', state);
    47→
    48→    state.government.activeRegulations.push('Large Company AI Safety Standards');
    49→    state.government.capabilityToControl += 0.2 * effects.effectivenessMultiplier;
    50→    state.government.regulationCount += 1;
    51→    state.government.oversightLevel = Math.min(10, state.government.oversightLevel + 0.5);
    52→
    53→    // Legitimacy boost - popular to regulate big tech
    54→    state.government.legitimacy = Math.min(1.0, state.government.legitimacy + 0.1);
    55→
    56→    // Economic cost (low)
    57→    state.globalMetrics.socialStability -= effects.enforcementCost;
    58→
    59→    return {
    60→      success: true,
    61→      effects: {
    62→        control_increase: 0.2 * effects.effectivenessMultiplier,
    63→        legitimacy_boost: 0.1,
    64→        racing_dynamics: effects.racingDynamicsMultiplier
    65→      },
    66→      events: [{
    67→        id: generateUniqueId('regulation_large_companies'),
    68→        timestamp: state.currentMonth,
    69→        type: 'action',
    70→        severity: 'info',
    71→        agent: 'Government',
    72→        title: 'Large Company Regulation Enacted',
    73→        description: `Government mandates safety standards for major AI companies. Popular with public, but small labs and open source continue unchecked. Racing dynamics may intensify.`,
    74→        effects: { regulatory_compliance: 0.2 }
    75→      }],
    76→      message: `Implemented large company regulation (effective but small labs escape)`
    77→    };
    78→  }
    79→};
    80→
    81→/**
    82→ * Regulate Compute Threshold
    83→ * Very effective but costly with surveillance risk
    84→ */
    85→const regulateComputeThreshold: CategorizedGovernmentAction = {
    86→  id: 'regulate_compute_threshold',
    87→  name: 'Regulate Compute Threshold',
    88→  description: 'Restrict training runs above compute threshold (very effective, high cost, surveillance risk)',
    89→  agentType: 'government',
    90→  category: 'regulation',
    91→  energyCost: 3,
    92→
    93→  canExecute: (state: GameState): boolean => {
    94→    return state.government.controlDesire > 0.5 &&
    95→           state.government.legitimacy > 0.4 && // Need legitimacy for unpopular measure
    96→           state.government.structuralChoices.regulationType === 'none';
    97→  },
    98→
    99→  execute: (state: GameState, agentId?: string, random = Math.random): ActionResult => {
   100→    // Set regulation type
   101→    state.government.structuralChoices.regulationType = 'compute_threshold';
   102→
   103→    const effects = calculateRegulationStructuralEffects('compute_threshold', state);
   104→
   105→    state.government.activeRegulations.push('Compute Threshold Monitoring');
   106→    state.government.capabilityToControl += 0.2 * effects.effectivenessMultiplier;
   107→    state.government.regulationCount += 1;
   108→    state.government.oversightLevel = Math.min(10, state.government.oversightLevel + 1.0);
   109→
   110→    // Legitimacy cost - technical and unpopular
   111→    state.government.legitimacy = Math.max(0, state.government.legitimacy - 0.15);
   112→
   113→    // High economic cost
   114→    state.globalMetrics.socialStability -= effects.enforcementCost;
   115→
   116→    // Surveillance increase from monitoring infrastructure
   117→    state.government.structuralChoices.surveillanceLevel =
   118→      Math.min(1.0, state.government.structuralChoices.surveillanceLevel + 0.15);
   119→
   120→    return {
   121→      success: true,
   122→      effects: {
   123→        control_increase: 0.2 * effects.effectivenessMultiplier,
   124→        legitimacy_cost: -0.15,
   125→        economic_cost: effects.enforcementCost,
   126→        surveillance_increase: 0.15
   127→      },
   128→      events: [{
   129→        id: generateUniqueId('regulation_compute'),
   130→        timestamp: state.currentMonth,
   131→        type: 'action',
   132→        severity: 'warning',
   133→        agent: 'Government',
   134→        title: 'Compute Threshold Regulation Enacted',
   135→        description: `Government restricts access to large-scale compute. Very effective at controlling AI development, but high economic costs and surveillance infrastructure concerns.`,
   136→        effects: { regulatory_compliance: 0.28 }
   137→      }],
   138→      message: `Implemented compute threshold regulation (effective but costly and enables surveillance)`
   139→    };
   140→  }
   141→};
   142→
   143→/**
   144→ * Regulate by Capability Ceiling
   145→ * Measurement problems and black markets
   146→ */
   147→const regulateCapabilityCeiling: CategorizedGovernmentAction = {
   148→  id: 'regulate_capability_ceiling',
   149→  name: 'Regulate by Capability Ceiling',
   150→  description: 'Ban systems above capability threshold (measurement problems, black markets)',
   151→  agentType: 'government',
   152→  category: 'regulation',
   153→  energyCost: 2,
   154→
   155→  canExecute: (state: GameState): boolean => {
   156→    return state.government.controlDesire > 0.6 &&
   157→           state.government.structuralChoices.regulationType === 'none';
   158→  },
   159→
   160→  execute: (state: GameState, agentId?: string, random = Math.random): ActionResult => {
   161→    // Set regulation type
   162→    state.government.structuralChoices.regulationType = 'capability_ceiling';
   163→
   164→    const effects = calculateRegulationStructuralEffects('capability_ceiling', state);
   165→
   166→    state.government.activeRegulations.push('AI Capability Ceiling');
   167→    state.government.capabilityToControl += 0.2 * effects.effectivenessMultiplier;
   168→    state.government.regulationCount += 1;
   169→    state.government.oversightLevel = Math.min(10, state.government.oversightLevel + 0.8);
   170→
   171→    // Legitimacy cost - enforcement challenges create cynicism
   172→    state.government.legitimacy = Math.max(0, state.government.legitimacy - 0.08);
   173→
   174→    // Economic cost (medium)
   175→    state.globalMetrics.socialStability -= effects.enforcementCost;
   176→
   177→    // High surveillance needed for enforcement
   178→    state.government.structuralChoices.surveillanceLevel =
   179→      Math.min(1.0, state.government.structuralChoices.surveillanceLevel + 0.2);
   180→
   181→    return {
   182→      success: true,
   183→      effects: {
   184→        control_increase: 0.2 * effects.effectivenessMultiplier,
   185→        legitimacy_cost: -0.08,
   186→        enforcement_challenges: 0.3,
   187→        surveillance_increase: 0.2
   188→      },
   189→      events: [{
   190→        id: generateUniqueId('regulation_capability'),
   191→        timestamp: state.currentMonth,
   192→        type: 'action',
   193→        severity: 'warning',
   194→        agent: 'Government',
   195→        title: 'Capability Ceiling Regulation Enacted',
   196→        description: `Government bans AI systems above capability threshold. Enforcement challenges ahead: measurement problems, black markets, and high surveillance requirements.`,
   197→        effects: { regulatory_compliance: 0.14 }
   198→      }],
   199→      message: `Implemented capability ceiling regulation (enforcement challenges and surveillance risks)`
   200→    };
   201→  }
   202→};
   203→
   204→/**
   205→ * Implement Compute Governance
   206→ * Regulate access to computing power
   207→ */
   208→const implementComputeGovernance: CategorizedGovernmentAction = {
   209→  id: 'implement_compute_governance',
   210→  name: 'Implement Compute Governance',
   211→  description: 'Regulate access to computing power (very effective but costly)',
   212→  agentType: 'government',
   213→  category: 'regulation',
   214→  energyCost: 3,
   215→
   216→  canExecute: (state: GameState): boolean => {
   217→    const monthsSinceLastMajorPolicy = state.currentMonth - state.government.lastMajorPolicyMonth;
   218→    return monthsSinceLastMajorPolicy >= 10; // Major policy cooldown
   219→  },
   220→
   221→  execute: (state: GameState, agentId?: string, random = Math.random): ActionResult => {
   222→    // Track major policy
   223→    state.government.lastMajorPolicyMonth = state.currentMonth;
   224→    state.government.majorPoliciesThisYear += 1;
   225→
   226→    // Upgrade compute governance level
   227→    const currentLevel = state.government.computeGovernance;
   228→    const levels: Array<'none' | 'monitoring' | 'limits' | 'strict'> = ['none', 'monitoring', 'limits', 'strict'];
   229→    const currentIndex = levels.indexOf(currentLevel);
   230→
   231→    if (currentIndex >= levels.length - 1) {
   232→      return {
   233→        success: false,
   234→        effects: {},
   235→        events: [],
   236→        message: 'Already at maximum compute governance level'
   237→      };
   238→    }
   239→
   240→    const newLevel = levels[currentIndex + 1];
   241→    state.government.computeGovernance = newLevel;
   242→
   243→    // Effects based on level
   244→    const effects = {
   245→      monitoring: { economicCost: 0.05, publicSupport: -0.05, effectiveness: 'moderate' },
   246→      limits: { economicCost: 0.2, publicSupport: -0.15, effectiveness: 'high' },
   247→      strict: { economicCost: 0.4, publicSupport: -0.25, effectiveness: 'very high' }
   248→    };
   249→
   250→    const levelEffects = effects[newLevel as keyof typeof effects];
