    const year = options?.year || 2024;

    // Force refresh if requested
    if (options?.forceRefresh) {
      await cacheManager.forceRefresh('vdem');
    }

    // Try loading from cache
    const cached = await cacheManager.loadFromCache<VDemCache>('vdem');
    if (cached) {
